61	export const config = {
62	  matcher: [
63	    /*
64	     * Match all request paths except:
65	     * - _next/static (static assets)
66	     * - _next/image (image optimization)
67	     * - favicon.ico
68	     * - images, fonts, and other public static files
69	     */
70	    "/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|woff|woff2|ttf|otf)$).*)",
71	  ],
