1	import { createServerClient } from "@supabase/ssr";
2	import { NextResponse, type NextRequest } from "next/server";
3	import type { Database } from "./types";
4	
5	const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
6	const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
7	
8	if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
9	  throw new Error(
10	    "Missing Supabase environment variables. Set NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in .env.local",
11	  );
12	}
13	
14	export async function updateSession(request: NextRequest) {
15	  let supabaseResponse = NextResponse.next({ request });
16	
17	  const supabase = createServerClient<Database>(
18	    SUPABASE_URL!,
19	    SUPABASE_ANON_KEY!,
20	    {
21	      cookies: {
22	        getAll() {
23	          return request.cookies.getAll();
24	        },
25	        setAll(cookiesToSet) {
26	          cookiesToSet.forEach(({ name, value }) =>
27	            request.cookies.set(name, value),
28	          );
29	          supabaseResponse = NextResponse.next({ request });
30	          cookiesToSet.forEach(({ name, value, options }) =>
31	            supabaseResponse.cookies.set(name, value, options),
32	          );
33	        },
34	      },
35	    },
36	  );
37	
38	  // CRITICAL: call getUser() (not getSession()) — this refreshes the auth
39	  // token. Skipping or using getSession() will break auth cookies.
40	  const {
41	    data: { user },
42	  } = await supabase.auth.getUser();
43	
44	  return { supabaseResponse, user };
45	}
