14	export async function createClient() {
15	  const cookieStore = await cookies();
16	
17	  return createServerClient<Database>(SUPABASE_URL!, SUPABASE_ANON_KEY!, {
18	    cookies: {
19	      getAll() {
20	        return cookieStore.getAll();
21	      },
22	      setAll(cookiesToSet) {
23	        try {
