2	import { createClient } from "@/integrations/supabase/server";
3	
4	/**
5	 * Server-side guard for protected pages. Call at the top of a Server
6	 * Component page.tsx or layout.tsx. Redirects to /auth if no session.
7	 *
8	 * This is a second line of defense — the Next.js proxy (root proxy.ts)
9	 * is the first gate and should redirect before the RSC even runs. This
10	 * helper also returns the user so pages can use it directly.
11	 */
12	export async function requireUser() {
13	  const supabase = await createClient();
14	  const {
15	    data: { user },
16	  } = await supabase.auth.getUser();
17	
18	  if (!user) {
19	    redirect("/auth");
20	  }
21	  return user;
22	}
23	
24	/**
25	 * Server-side guard for admin-only pages. Verifies both session AND
26	 * admin role via user_roles table.
27	 */
28	export async function requireAdmin() {
29	  const supabase = await createClient();
30	  const {
31	    data: { user },
32	  } = await supabase.auth.getUser();
33	
34	  if (!user) {
35	    redirect("/auth");
36	  }
37	
38	  const { data: roles } = await supabase
39	    .from("user_roles")
40	    .select("role")
41	    .eq("user_id", user.id);
42	
43	  const isAdmin = (roles ?? []).some(
44	    (r: { role: string }) => r.role === "admin",
45	  );
46	  if (!isAdmin) {
47	    redirect("/");
48	  }
49	
50	  return user;
51	}
