54	 * Optional user fetch — returns null if not logged in, does not redirect.
55	 * Use in pages that render different content for anon vs logged-in users.
56	 */
57	export async function getOptionalUser() {
58	  const supabase = await createClient();
59	  const {
60	    data: { user },
61	  } = await supabase.auth.getUser();
62	  return user;
63	}
