3	import { useState, useEffect, createContext, useContext, useRef } from "react";
4	import { supabase } from "@/integrations/supabase/browser";
5	import type { User, Session } from "@supabase/supabase-js";
6	
7	type Profile = {
8	  credits: number;
9	  subscription_credits: number;
10	  topup_credits: number;
11	  bonus_credits: number;
12	  inbox_email: string | null;
13	  plan: string;
14	  email_enabled: boolean;
15	  auto_rank_enabled: boolean;
16	  subscription_ends_at: string | null;
17	};
18	
19	interface AuthContextType {
20	  user: User | null;
21	  session: Session | null;
22	  loading: boolean;
23	  isAdmin: boolean;
24	  profile: Profile | null;
25	  signOut: () => Promise<void>;
26	  refreshProfile: () => Promise<void>;
27	}
28	
29	const AuthContext = createContext<AuthContextType>({
30	  user: null,
31	  session: null,
32	  loading: true,
33	  isAdmin: false,
34	  profile: null,
35	  signOut: async () => {},
36	  refreshProfile: async () => {},
37	});
38	
39	// eslint-disable-next-line react-refresh/only-export-components
40	export const useAuth = () => useContext(AuthContext);
41	
42	export function AuthProvider({ children }: { children: React.ReactNode }) {
43	  const [user, setUser] = useState<User | null>(null);
44	  const [session, setSession] = useState<Session | null>(null);
45	  const [loading, setLoading] = useState(true);
46	  const [isAdmin, setIsAdmin] = useState(false);
47	  const [profile, setProfile] = useState<Profile | null>(null);
48	  const userIdRef = useRef<string | null>(null);
49	
50	  const fetchProfile = async (userId: string) => {
51	    try {
52	      const { data } = await supabase
53	        .from("profiles")
54	        .select(
55	          "credits, subscription_credits, topup_credits, bonus_credits, inbox_email, plan, email_enabled, auto_rank_enabled, subscription_ends_at",
56	        )
57	        .eq("user_id", userId)
58	        .single();
59	      if (data) setProfile(data as Profile);
60	    } catch (err) {
61	      console.error("[useAuth] Error fetching profile:", err);
62	    }
63	  };
64	
65	  const fetchRole = async (userId: string) => {
66	    try {
67	      const { data } = await supabase
68	        .from("user_roles")
69	        .select("role")
70	        .eq("user_id", userId);
71	      setIsAdmin(
72	        (data ?? []).some((r: { role: string }) => r.role === "admin"),
73	      );
74	    } catch (err) {
75	      console.error("[useAuth] Error fetching role:", err);
76	    }
77	  };
78	
79	  const refreshProfile = async () => {
80	    if (userIdRef.current) await fetchProfile(userIdRef.current);
81	  };
82	
83	  useEffect(() => {
84	    const {
85	      data: { subscription },
86	    } = supabase.auth.onAuthStateChange(async (_event, nextSession) => {
87	      setSession(nextSession);
88	      setUser(nextSession?.user ?? null);
89	      userIdRef.current = nextSession?.user?.id ?? null;
90	
91	      if (nextSession?.user) {
92	        // setTimeout avoids the Supabase deadlock inside onAuthStateChange
93	        setTimeout(async () => {
94	          await Promise.all([
95	            fetchProfile(nextSession.user.id),
96	            fetchRole(nextSession.user.id),
97	          ]);
98	        }, 0);
99	      } else {
100	        setProfile(null);
101	        setIsAdmin(false);
102	      }
103	      setLoading(false);
104	    });
105	
106	    supabase.auth.getSession().then(async ({ data: { session: initial } }) => {
107	      setSession(initial);
108	      setUser(initial?.user ?? null);
109	      userIdRef.current = initial?.user?.id ?? null;
110	      if (initial?.user) {
111	        await Promise.all([
112	          fetchProfile(initial.user.id),
113	          fetchRole(initial.user.id),
114	        ]);
115	      }
116	      setLoading(false);
117	    });
118	
119	    return () => subscription.unsubscribe();
120	  }, []);
121	
122	  // Refresh profile on window focus + every 2min to keep credits current
123	  useEffect(() => {
124	    if (!user) return;
125	    const handleFocus = () => fetchProfile(user.id);
126	    window.addEventListener("focus", handleFocus);
127	    const interval = setInterval(() => fetchProfile(user.id), 120_000);
128	    return () => {
129	      window.removeEventListener("focus", handleFocus);
130	      clearInterval(interval);
131	    };
132	    // Intentional: re-run only on user identity change (id), not on every
133	    // Supabase user object reference change. fetchProfile is stable because
134	    // it closes over `supabase` which is a module singleton.
135	    // eslint-disable-next-line react-hooks/exhaustive-deps
136	  }, [user?.id]);
137	
138	  const signOut = async () => {
139	    await supabase.auth.signOut();
140	    setUser(null);
141	    setSession(null);
142	    setProfile(null);
143	    setIsAdmin(false);
144	  };
145	
146	  return (
147	    <AuthContext.Provider
148	      value={{ user, session, loading, isAdmin, profile, signOut, refreshProfile }}
149	    >
150	      {children}
151	    </AuthContext.Provider>
152	  );
153	}
